#include <boost/math/special_functions/factorials.hpp>
#include <complex>

typedef std::complex<double> dcomp;

dcomp calculate_coherent_element_test(unsigned long n, dcomp alpha) {
    if (n == 0) {
        return dcomp(1.);
    }

    // For small n, use the exact formula: alpha^n/sqrt(n!)
    if (n < 20) {  // Using a reasonable threshold before switching to Stirling approximation
        dcomp alpha_n = std::pow(alpha, (int)n);
        double n_factorial = boost::math::factorial<double>(n);
        double sqrt_n_factorial = std::sqrt(n_factorial);
        return alpha_n / sqrt_n_factorial;
    }

    // Use Stirling's approximation for large n to avoid overflow
    const double PI = 3.14159265358979323846;
    const double E = 2.71828182845904523536;

    // Stirling's approximation: n! ≈ sqrt(2πn) * (n/e)^n
    double stirling_approx = std::sqrt(2 * PI * n) * std::pow(n / E, (double)n);
    double sqrt_stirling = std::sqrt(stirling_approx);

    // For coherent states: |α|^n * exp(-|α|²/2) / sqrt(n!)
    // But we just need the coefficient: α^n / sqrt(n!)
    dcomp alpha_n = std::pow(alpha, (int)n);
    return alpha_n / sqrt_stirling;
}

